'use client';

import * as React from 'react';
import { CheckIcon } from 'lucide-react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';
import { formatMoney } from '@/lib/money';
import type { BillingInterval, PlanView } from '@/types/billing-ui';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';

const planCardShell = cva('relative h-full transition-[box-shadow,ring-color]', {
  variants: {
    emphasis: {
      default: '',
      recommended: 'z-[1] ring-1 ring-primary/30 shadow-sm',
    },
  },
  defaultVariants: { emphasis: 'default' },
});

export interface PlanCardProps
  extends Omit<React.ComponentProps<typeof Card>, 'onSelect'>,
    VariantProps<typeof planCardShell> {
  plan?: PlanView;
  interval?: BillingInterval;
  currencyFallback?: string;
  onSelect?: (planId: string, interval: BillingInterval) => void;
}

/**
 * Compound plan surface. Use parts freely, or pass `plan` for a ready layout.
 */
function PlanCard({
  className,
  emphasis,
  plan,
  interval = 'month',
  currencyFallback = 'IDR',
  onSelect,
  children,
  elevated,
  ...props
}: PlanCardProps) {
  const resolvedEmphasis = emphasis ?? (plan?.recommended ? 'recommended' : 'default');
  const isElevated = elevated ?? Boolean(plan?.recommended);

  if (plan && !children) {
    const currency = plan.currency ?? currencyFallback;
    const amount = interval === 'year' ? plan.yearlyAmount : plan.monthlyAmount;
    const period = interval === 'year' ? '/ year' : '/ month';

    return (
      <Card
        data-slot="plan-card"
        elevated={isElevated}
        className={cn(
          planCardShell({ emphasis: resolvedEmphasis }),
          plan?.recommended && 'overflow-hidden',
          className,
        )}
        {...props}
      >
        {plan?.recommended ? (
          <div
            data-slot="plan-card-shader-strip"
            className="pointer-events-none absolute inset-x-0 top-0 z-[2] h-[3px] overflow-hidden rounded-t-[inherit]"
            aria-hidden
            style={{
              background:
                'linear-gradient(90deg, var(--shader-cyan), var(--primary-soft), var(--shader-lavender), var(--primary-subtle))',
            }}
          />
        ) : null}
        <CardHeader className="gap-3">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <CardTitle className="min-w-0 flex-1 text-lg">{plan.name}</CardTitle>
            {plan.badge || plan.recommended ? (
              <Badge tone={plan.recommended ? 'default' : 'muted'} className="shrink-0">
                {plan.badge ?? 'Recommended'}
              </Badge>
            ) : null}
          </div>
          {plan.description ? (
            <CardDescription className="leading-relaxed">{plan.description}</CardDescription>
          ) : null}
        </CardHeader>
        <CardContent className="flex min-w-0 flex-1 flex-col gap-6">
          <PlanCardPrice amount={amount} currency={currency} period={period} />
          <PlanCardFeatures features={plan.features} />
        </CardContent>
        <CardFooter className="min-w-0 shrink-0">
          <Button
            className="w-full min-w-0"
            size="lg"
            variant={plan.recommended ? 'default' : 'outline'}
            onClick={() => onSelect?.(plan.id, interval)}
          >
            {plan.ctaLabel ?? 'Select plan'}
          </Button>
        </CardFooter>
      </Card>
    );
  }

  return (
    <Card
      data-slot="plan-card"
      elevated={isElevated}
      className={cn(planCardShell({ emphasis: resolvedEmphasis }), className)}
      {...props}
    >
      {children}
    </Card>
  );
}

function PlanCardHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return <CardHeader data-slot="plan-card-header" className={className} {...props} />;
}

function PlanCardTitle({ className, ...props }: React.ComponentProps<'div'>) {
  return <CardTitle data-slot="plan-card-title" className={className} {...props} />;
}

function PlanCardDescription({ className, ...props }: React.ComponentProps<'div'>) {
  return <CardDescription data-slot="plan-card-description" className={className} {...props} />;
}

export interface PlanCardPriceProps extends React.ComponentProps<'div'> {
  amount: number;
  currency?: string;
  period?: string;
}

function PlanCardPrice({
  amount,
  currency = 'IDR',
  period = '/ month',
  className,
  ...props
}: PlanCardPriceProps) {
  return (
    <div
      data-slot="plan-card-price"
      className={cn('flex flex-wrap items-baseline gap-x-2 gap-y-1', className)}
      {...props}
    >
      <span className="break-words text-3xl font-semibold tracking-tight tabular-nums sm:text-[2rem]">
        {formatMoney(amount, { currency })}
      </span>
      {period ? (
        <span className="shrink-0 text-sm font-medium text-muted-foreground">{period}</span>
      ) : null}
    </div>
  );
}

export interface PlanCardFeaturesProps extends React.ComponentProps<'ul'> {
  features: PlanView['features'];
}

function PlanCardFeatures({ features, className, ...props }: PlanCardFeaturesProps) {
  return (
    <ul
      data-slot="plan-card-features"
      className={cn('flex flex-col gap-3', className)}
      {...props}
    >
      {features.map((feature) => (
        <li key={feature.id} className="flex items-start gap-3 text-sm leading-relaxed">
          <CheckIcon
            className={cn(
              'mt-0.5 size-4 shrink-0',
              feature.included === false ? 'text-muted-foreground/40' : 'text-primary/70',
            )}
            aria-hidden
          />
          <span className={cn(feature.included === false && 'text-muted-foreground line-through')}>
            {feature.label}
          </span>
        </li>
      ))}
    </ul>
  );
}

function PlanCardFooter({ className, ...props }: React.ComponentProps<'div'>) {
  return <CardFooter data-slot="plan-card-footer" className={className} {...props} />;
}

export {
  PlanCard,
  PlanCardHeader,
  PlanCardTitle,
  PlanCardDescription,
  PlanCardPrice,
  PlanCardFeatures,
  PlanCardFooter,
};
